MOD=SUB/'persistent_profit_runtime.py'
MOD.write_text('from __future__ import annotations\nimport argparse,asyncio,json,os,signal,time\nfrom pathlib import Path\nfrom time import perf_counter_ns\n\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot import merged_live_runtime as m\n\nHEARTBEAT_SECONDS=float(os.getenv("QARB_HEARTBEAT_SECONDS","15"))\nRECONNECT_MIN=float(os.getenv("QARB_WS_RECONNECT_MIN_SECONDS","1"))\nRECONNECT_MAX=float(os.getenv("QARB_WS_RECONNECT_MAX_SECONDS","30"))\nQUEUE_MAX=int(os.getenv("QARB_EVENT_QUEUE_MAX","20000"))\nMAX_PAIRS=int(os.getenv("QARB_PERSISTENT_MAX_PAIRS","12"))\n_STOP=False\n\ndef _stop(*_):\n    global _STOP\n    _STOP=True\n\ndef _p99(xs):\n    if not xs: return None\n    y=sorted(xs)\n    return y[min(len(y)-1,int(len(y)*.99))]\n\ndef _best_text(best):\n    if not best: return "None"\n    return "%+.9f_SOL %+.2f_bps %s->%s"%(\n        best["net_sol"],best["net_bps"],best["buy_venue"],best["sell_venue"])\n\ndef _process_event(state,ev,c):\n    a=ev["address"];tokens=set();priced=False\n    if a in state["preg"]:\n        i,k=state["preg"][a];p=state["pairs"][i]\n        try:\n            if m.pd.apply_account_event(p,k,a,ev["raw"],ev["slot"],ev["received_ns"]):\n                tokens.add(p.token);priced=True\n        except Exception:\n            c["event_errors"]+=1\n    if a in state["creg"]:\n        i,d=state["creg"][a];dd,st=state["cstates"][i]\n        try:\n            if m.rc.update(st,dd,a,ev["raw"],ev["received_ns"]):\n                ep=m._cpmm_ep(dd,st)\n                if ep:\n                    tokens.add(ep.token);priced=True\n        except Exception:\n            c["event_errors"]+=1\n    if not priced:\n        if a in state["observed"]:\n            c["observed_only_events"]+=1\n        return\n    c["priced_events"]+=1\n    for token in tokens:\n        r=m.evaluate_token(token,state["eps"].get(token,()),state["landing"],ev["received_ns"])\n        if not r: continue\n        c["lat"].append(float(r["event_to_decision_ms"]))\n        if c["best"] is None or r["net_sol"]>c["best"]["net_sol"]:\n            c["best"]=r\n        if r["qualified"]:\n            c["signals"]+=1\n            print("[HOT_SIGNAL] token=%s buy=%s sell=%s size=%.6f net=%+.9f SOL bps=%+.2f age_ms=%.3f"%(\n                token[:10],r["buy_venue"],r["sell_venue"],r["size_sol"],\n                r["net_sol"],r["net_bps"],r["event_to_decision_ms"]),flush=True)\n\ndef _initial_scan(state,c):\n    now=perf_counter_ns()\n    for token,eps in state["eps"].items():\n        r=m.evaluate_token(token,eps,state["landing"],now)\n        if not r: continue\n        if c["best"] is None or r["net_sol"]>c["best"]["net_sol"]:\n            c["best"]=r\n        if r["qualified"]:\n            c["signals"]+=1\n            print("[HOT_SIGNAL_INITIAL] token=%s buy=%s sell=%s size=%.6f net=%+.9f SOL bps=%+.2f"%(\n                token[:10],r["buy_venue"],r["sell_venue"],r["size_sol"],r["net_sol"],r["net_bps"]),flush=True)\n\nasync def _worker(index,addresses,q,c,stop):\n    import websockets\n    await asyncio.sleep(index*m.STAGGER_SECONDS)\n    delay=RECONNECT_MIN\n    while not stop.is_set():\n        by_id={i+1:a for i,a in enumerate(addresses)}\n        submap={}\n        try:\n            async with websockets.connect(\n                m.WS_URL,ping_interval=20,ping_timeout=20,close_timeout=3,max_size=8_000_000\n            ) as ws:\n                c["connections"]+=1\n                for req in m._req(addresses):\n                    if stop.is_set(): break\n                    await ws.send(json.dumps(req,separators=(",",":")))\n                    if m.SUB_DELAY_MS>0: await asyncio.sleep(m.SUB_DELAY_MS/1000.0)\n                delay=RECONNECT_MIN\n                while not stop.is_set():\n                    try:\n                        raw=await asyncio.wait_for(ws.recv(),timeout=1.0)\n                    except asyncio.TimeoutError:\n                        continue\n                    msg=json.loads(raw)\n                    if "id" in msg and isinstance(msg.get("result"),int):\n                        a=by_id.get(int(msg["id"]))\n                        if a:\n                            submap[int(msg["result"])]=a;c["acks"]+=1\n                        continue\n                    ev=m._parse(msg,submap)\n                    if not ev: continue\n                    c["notifications"]+=1\n                    try:q.put_nowait(ev)\n                    except asyncio.QueueFull:c["queue_drops"]+=1\n        except asyncio.CancelledError:\n            raise\n        except Exception as exc:\n            txt=f"{type(exc).__name__}: {exc}"\n            c["reconnects"]+=1;c["last_ws_error"]=txt\n            low=txt.lower()\n            if "1013" in low or "rate limit" in low or "too many subscriptions" in low:\n                c["rate_limit_disconnects"]+=1\n            print("[WS_RECOVER] shard=%d error=%s retry_in=%.1fs"%(index,txt,delay),flush=True)\n            await asyncio.sleep(delay)\n            delay=min(RECONNECT_MAX,max(RECONNECT_MIN,delay*2))\n\nasync def serve(root,max_seconds=None):\n    root=Path(root)\n    # Increase one-time warm coverage, then NEVER rediscover during steady-state.\n    m.pd.MAX_PAIRS=MAX_PAIRS\n    state=m.prepare(root)\n    caps=m.capability(state)\n    shards=m._shards(state["addresses"])\n    c={"acks":0,"notifications":0,"priced_events":0,"observed_only_events":0,\n       "signals":0,"event_errors":0,"queue_drops":0,"connections":0,"reconnects":0,\n       "rate_limit_disconnects":0,"last_ws_error":None,"lat":[],"best":None}\n    print("[QARB-022D] PERSISTENT MRIYA-STYLE PROFIT RUNTIME",flush=True)\n    print("[DISCOVERY] one startup hydration only; no 30-second REST rebuild",flush=True)\n    print("[PRICED] PumpSwap | Meteora DLMM | hydrated Raydium CPMM",flush=True)\n    print("[CAPABILITY] "+json.dumps(caps,sort_keys=True),flush=True)\n    print("[LIVE] accounts=%d shards=%d priced_tokens=%d max_pairs=%d"%(\n        len(state["addresses"]),len(shards),len(state["eps"]),MAX_PAIRS),flush=True)\n    print("[GATE] profitable route emitted immediately; state age <=750ms",flush=True)\n    print("[MODE] scanner/handoff only execution_authority=FALSE",flush=True)\n\n    _initial_scan(state,c)\n    q=asyncio.Queue(maxsize=QUEUE_MAX);stop=asyncio.Event()\n    workers=[asyncio.create_task(_worker(i,s,q,c,stop)) for i,s in enumerate(shards)]\n    started=time.monotonic();last_hb=started;last_n=0\n\n    try:\n        while not stop.is_set():\n            if _STOP: break\n            if max_seconds is not None and time.monotonic()-started>=float(max_seconds): break\n            try:\n                ev=await asyncio.wait_for(q.get(),timeout=.25)\n                _process_event(state,ev,c)\n            except asyncio.TimeoutError:\n                pass\n            now=time.monotonic()\n            if now-last_hb>=HEARTBEAT_SECONDS:\n                span=max(.001,now-last_hb)\n                eps=(c["notifications"]-last_n)/span\n                print("[HEARTBEAT] uptime_s=%d notifications=%d eps=%.2f priced_events=%d signals=%d best=%s p99_ms=%s reconnects=%d rate_limits=%d"%(\n                    int(now-started),c["notifications"],eps,c["priced_events"],c["signals"],\n                    _best_text(c["best"]),str(_p99(c["lat"])),c["reconnects"],c["rate_limit_disconnects"]),flush=True)\n                last_hb=now;last_n=c["notifications"]\n    finally:\n        stop.set()\n        for t in workers:t.cancel()\n        await asyncio.gather(*workers,return_exceptions=True)\n\n    return {"notifications":c["notifications"],"priced_events":c["priced_events"],\n            "observed_only_events":c["observed_only_events"],"signals":c["signals"],\n            "best":c["best"],"acks":c["acks"],"connections":c["connections"],\n            "reconnects":c["reconnects"],"rate_limit_disconnects":c["rate_limit_disconnects"],\n            "p99_event_to_decision_ms":_p99(c["lat"]),"priced_tokens":len(state["eps"]),\n            "accounts":len(state["addresses"]),"capability":caps,\n            "execution_authority":False}\n\ndef main(argv=None):\n    ap=argparse.ArgumentParser()\n    ap.add_argument("--seconds",type=float,default=None,help="omit for continuous 24/7")\n    a=ap.parse_args(argv)\n    signal.signal(signal.SIGINT,_stop)\n    if hasattr(signal,"SIGTERM"):signal.signal(signal.SIGTERM,_stop)\n    r=asyncio.run(serve(Path.cwd(),a.seconds))\n    print("[RESULT] "+json.dumps(r,sort_keys=True),flush=True)\n    return r\n\nif __name__=="__main__":main()\n',encoding='utf-8')
py_compile.compile(str(MOD),doraise=True)

TEST=ROOT/'test_qarb_022d_persistent_mriya_style_profit_runtime.py'
TEST.write_text('import asyncio,unittest\nfrom time import perf_counter_ns\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot.persistent_profit_runtime import _p99,_best_text\n\nclass T(unittest.TestCase):\n    def test_p99(self):\n        self.assertEqual(_p99([1,2,3]),3)\n        print("[PASS] latency scoreboard p99")\n    def test_best_text(self):\n        x={"net_sol":.001,"net_bps":20.0,"buy_venue":"A","sell_venue":"B"}\n        self.assertIn("+0.001000000_SOL",_best_text(x))\n        print("[PASS] heartbeat surfaces live best PNL")\n    def test_no_window_rediscovery_contract(self):\n        import inspect\n        from qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot import persistent_profit_runtime as p\n        src=inspect.getsource(p.serve)\n        self.assertEqual(src.count("m.prepare(root)"),1)\n        self.assertNotIn("while True:\\n        state=m.prepare",src)\n        print("[PASS] production state hydrates once; no recurring REST discovery loop")\nif __name__=="__main__":unittest.main(verbosity=2)\n',encoding='utf-8')
py_compile.compile(str(TEST),doraise=True)

